import os
from subject import check_critical_env_vars, ModelEnvHealthResult, CRITICAL_ENV_VARS


def test_check_critical_env_vars_all_set():
    # Save original environment
    original_env = {k: os.environ.get(k) for k, _ in CRITICAL_ENV_VARS}
    try:
        # Set both critical env vars
        os.environ["INTELLIGENCE_SERVICE_URL"] = "http://example.com"
